from ta_emss.utilities.trs.commands.emssim import EmssimCommand


class Auto_sdl(EmssimCommand):
    def __init__(self, method="auto_sdl", timeout=60, rpc_connection_name='localRPC'):
        super(Auto_sdl, self).__init__(method, timeout, rpc_connection_name)
        self.params = None

    def on_new_data(self, **data):
        data = super(Auto_sdl, self).on_new_data(**data)
        if 'msg' in data:
            self._ret = data
